"""GRPO shape: story_pure — long-story variant (50 samples).

Companion to shape_story_pure.py. Each user_goal starts with "Here's my
story I want to process: " followed by an original ~150-200 word story
plus an illustration-style modifier. Same chain: Narration → Illustration
→ Narrator → Compositor.
"""
from __future__ import annotations


def _make(theme, art_style, descriptor):
    return {
        "rationale": (
            f"{theme} from a user-provided story + {art_style} illustrations + "
            "slideshow narration."
        ),
        "intents": [
            f"Write the narration script from the user's supplied {descriptor}.",
            f"Generate one {art_style} illustration per scene of the {descriptor}.",
            f"Produce a measured TTS narrator track for the {descriptor}.",
            f"Compose the final slideshow pairing {art_style} illustrations with the narrator audio.",
        ],
    }


SAMPLES: list[dict] = [
    {**_make("Bedtime rabbit-and-seed tale", "soft watercolor", "rabbit-and-glowing-seed bedtime tale"),
     "user_goal": "Here's my story I want to process — soft watercolor please: There once was a small brown rabbit named Pip who lived in a meadow at the edge of a sleeping forest. One evening, just as the moon was rising, Pip found a seed that glowed like a tiny lantern. The other rabbits had all run home for the night, but Pip was curious. The seed was warm in his paw. He carried it home through the long grass and set it carefully on his doorstep. By morning the seed had grown into a single white flower, and the flower had a voice. It thanked Pip for finding it and said it had been lost for one hundred years. Pip blinked his sleepy eyes and asked the flower if it would like to come live in his garden. The flower said yes. They became great friends, and every spring after that, the meadow filled with one hundred glowing white flowers, all from the one Pip had brought home."},
    {**_make("Polar-bear-cub winter storytime", "soft pastel", "polar-bear-cub winter storytime"),
     "user_goal": "Here's my story I want to process — soft pastel please: In the far north, where the sea freezes solid each winter, a young polar bear cub named Nuna was learning how to hunt. Her mother had taught her to listen for seals beneath the ice, but the ice was moving, and Nuna was afraid. The wind blew snow into her face. Her paws sank into a soft drift. Far away she heard her mother calling. Nuna turned to follow the call, but a sudden crack ran across the ice between them. Nuna was alone on a small white island that drifted slowly out to sea. She did not panic. She listened for her mother's voice and walked carefully to the edge of her island and dove into the cold water. She was a strong swimmer. She reached the larger ice in twenty heartbeats. Her mother was there waiting. Nuna had learned that day that fear is a small thing in a big world."},
    {**_make("Norse Fenrir-wolf myth", "bold woodcut", "Fenrir-wolf myth"),
     "user_goal": "Here's my story I want to process — bold woodcut style: When the great wolf Fenrir was still a pup, the gods of Asgard raised him in their halls because his mother was a giantess they wished to honor. The pup grew larger every day. Soon he was as tall as a horse. Then as tall as the great hall itself. The gods grew afraid. They forged a chain to bind him, but Fenrir snapped it in his sleep. They forged a heavier chain, but he broke that one too with one stretch of his shoulders. The dwarves of the deep mountain forged a third — a thin ribbon made from the sound of a cat's footstep, the breath of a fish, and the roots of a mountain. The ribbon held. Fenrir, when he understood he had been bound by treachery, did not howl in anger. He simply closed his eyes and waited for the end of the world."},
    {**_make("Glass-castle wizard fable", "whimsical cartoon", "glass-castle wizard fable"),
     "user_goal": "Here's my story I want to process — whimsical cartoon style: An old wizard named Bertram lived alone in a glass castle on top of a glass mountain. He had built it himself, three hundred years before, when he was young and arrogant and wanted to be seen. People came from far away to admire his castle. They threw stones at it sometimes, just to see the cracks heal themselves. Bertram had grown tired of being admired. One day a small girl climbed his mountain and asked him, very politely, if she could come inside. Bertram looked at her for a long moment and said yes. She stayed for tea. She said the castle was beautiful but it was lonely. Bertram had never thought about that. The next morning he opened all the doors of the castle and invited the village to come and live in it with him. They came. The castle was full of laughter for the rest of his life."},
    {**_make("Japanese kappa river-spirit tale", "ukiyo-e", "kappa river-spirit tale"),
     "user_goal": "Here's my story I want to process — ukiyo-e style: In a small village by a slow green river there lived a kappa, a water-spirit with a turtle's shell and a small bowl of water on top of his head. The kappa was not a kindly creature. He liked to pull horses into the river to drown them. The villagers were afraid. One spring a brave young woman named Hina went down to the river and bowed to the kappa, very deeply. The kappa, who had never received a bow, was so surprised that he bowed back. The water in his bowl spilled. Without his water the kappa lost his power. Hina helped him find a new pool to fill his bowl, and made him promise — politely, with another bow — never to harm a horse again. The kappa kept his promise. Every spring after that the villagers left him a cucumber by the river bank, his favorite food."},
    {**_make("Vietnamese water-buffalo folktale", "ink-and-wash", "water-buffalo and-rice-grain folktale"),
     "user_goal": "Here's my story I want to process — ink-and-wash style: Long ago in the Red River delta there lived a water buffalo named Trâu who pulled the plow in the rice paddies of an old farmer. Trâu was patient and strong. One day, while resting in the shade, Trâu found a single grain of rice on a rock. The grain spoke and said it was the last grain from a harvest a hundred years ago, and that if Trâu planted it, the rice would feed the village for a hundred more years. Trâu carried the grain on his nose all the way back to the paddy. He pressed it into the mud with his hoof. By harvest time the paddy yielded twice as much rice as any year before. The farmer thanked Trâu and never asked him to pull the plow again. Trâu lived in the shade of the rice paddy for the rest of his long, lazy life, and the village always had enough."},
    {**_make("Panchatantra blue-jackal fable", "Mughal-miniature", "blue-jackal fable"),
     "user_goal": "Here's my story I want to process — Mughal-miniature style: A jackal named Chandaraka was running through a town when a pack of dogs began chasing him. He ducked into a vat of indigo dye and hid until the dogs were gone. When he climbed out, his fur was brilliant blue. The other animals of the forest had never seen anything like it. They thought he was a magical creature sent by the gods. Chandaraka, sensing his chance, declared himself their king. He sat on a high rock and accepted their tributes. The lions hunted for him. The deer paid in fruit. Chandaraka grew lazy and proud. One night a pack of jackals passed by and howled. Chandaraka, who could not help himself, howled back. The animals heard the howl and recognized him as a jackal. They drove him from the forest. The moral, the storytellers say, is that no costume hides what you truly are forever."},
    {**_make("Cherokee Spider-and-fire creation", "Cherokee-textile-pattern", "Spider-Grandmother and fire creation"),
     "user_goal": "Here's my story I want to process — Cherokee-textile-pattern style: In the time when the world was new, there was no fire on the earth. The animals were cold. They held a council. The fox tried to bring fire from the sun and burned his tail black. The crow tried and burned all her feathers; she had been white before. The opossum tried and singed off most of her fur. None of the strong, quick animals could carry the fire home. At last Spider-Grandmother spoke up. She was small and old and had been watching the others. She wove a small clay pot, climbed up to the sun on her thread, scooped a coal of fire into the pot, and carried it gently down. She gave the fire to the people. The people gave thanks to Spider-Grandmother and to the small clay pot, and from that day on, every Cherokee weaver wove a spiderweb pattern into her cloth in honor."},
    {**_make("Aboriginal Rainbow-Serpent shaping", "Aboriginal-dot-painting", "Rainbow-Serpent landscape-shaping story"),
     "user_goal": "Here's my story I want to process — Aboriginal-dot-painting style: In the Dreamtime, when the land was flat and dry, the great Rainbow Serpent woke from her long sleep beneath the desert. She stretched, and her body moved across the land, and where her body moved, the rivers were carved into the earth. She lifted her head, and the mountains rose up to meet her. She breathed, and the rains came. The animals woke as she passed and took the shapes she had dreamed for them. The first people followed in her path and learned the songs of the country from her movement. The Rainbow Serpent now sleeps again beneath the deepest waterholes. The elders say she still listens. When the rains come heavy and the rivers swell, they say it is the Rainbow Serpent stirring in her sleep, reminding the people that the country is alive and that they belong to it, not the other way around."},
    {**_make("Caribbean Anansi-and-tiger trickster", "bright Caribbean-palette", "Anansi-and-tiger trickster tale"),
     "user_goal": "Here's my story I want to process — bright Caribbean-palette style: One hot afternoon Brer Tiger called all the small creatures of the forest together and announced that, from now on, all the stories would be called tiger stories. Anansi the spider was very small but very clever. He climbed up onto a leaf and said, very politely, that he would be happy if Tiger would catch him a single hornet from the great hornet tree, and bring back a single live snake from the river, and bring back a single fast antelope from the grasslands. Then, Anansi said, the stories could be tiger stories forever. Tiger laughed at the small spider and went off to do all three. While he was gone, Anansi hurried home, gathered the other small creatures, and told them what he had asked. Tiger never returned with all three. Anansi kept the stories for himself, and that is why, in the islands, all the stories are still called Anansi stories."},
    {**_make("Egyptian Isis-search-for-Osiris myth", "Egyptian-papyrus", "Isis-search-for-Osiris myth"),
     "user_goal": "Here's my story I want to process — Egyptian-papyrus style: When the king of the gods, Osiris, was murdered by his jealous brother Set, his body was cut into fourteen pieces and scattered across the length of Egypt. His sister-wife, Isis, vowed to find every piece. She searched the desert. She searched the marshes of the Nile. She searched the mountains and the cliffs and the oases. She found thirteen pieces and gathered them. The fourteenth piece had fallen into the river and been eaten by a fish. Isis did not weep. She made a new piece from clay and breath and her own tears, and she joined all fourteen together, and she breathed life back into Osiris. He could not return to the world of the living. He became the king of the dead. But for one night every year, Isis is allowed to visit him in the underworld, and from that visit the world receives the rains."},
    {**_make("Inuit Sedna-sea-goddess myth", "Inuit-soapstone-carving", "Sedna sea-goddess myth"),
     "user_goal": "Here's my story I want to process — Inuit-soapstone-carving style: Sedna was a young Inuit woman who refused every man her father suggested as a husband. One day a strange handsome stranger came in a kayak from across the sea. Her father gave her to him. The stranger was not a man but a great seabird in disguise. He took Sedna to a barren island and kept her there. Sedna's father came to rescue her in his kayak. As they paddled home, the seabird stirred up a great storm. The storm was so terrible that Sedna's father, in fear, threw Sedna overboard to lighten the boat. When she clung to the side, he cut off her fingers. As her fingers fell into the sea they became the seals and the walruses and the whales. Sedna sank to the bottom and became the goddess of all the sea creatures. Now, when the seas are barren, the people send a shaman to comb her long hair so that she will release the animals."},
    {**_make("Welsh Pwyll-and-Annwn tale", "illuminated-manuscript", "Pwyll-and-Annwn-otherworld tale"),
     "user_goal": "Here's my story I want to process — illuminated-manuscript style: Pwyll, the prince of Dyfed, was hunting in the forest when he met a tall white-clad stranger with a pack of red-eared white hounds. The stranger was Arawn, the king of Annwn, the otherworld. Arawn proposed an exchange: that for one year, Pwyll would take Arawn's shape and rule the otherworld, while Arawn would take Pwyll's shape and rule Dyfed. Pwyll agreed. He went into the otherworld and ruled there for a year, and at the end of the year he met Arawn's enemy in single combat and defeated him. He returned to Dyfed and found Arawn had ruled justly in his place. The two kings met at the same forest crossroads. They restored their true shapes. They became friends for life. Pwyll, the storyteller says, learned in that year that a kingdom is judged not by the man who wears its crown but by what the crown asks of him."},
    {**_make("Persian Layla-and-Majnun romance", "Persian-miniature", "Layla-and-Majnun romance"),
     "user_goal": "Here's my story I want to process — Persian-miniature style: Qays and Layla had loved each other since childhood, but Layla's father refused to let them marry. Qays grieved so deeply that he wandered into the desert and lost his name. The people called him Majnun, which means madman. He composed verses about Layla and the wind carried them. Layla was given in marriage to a wealthy nobleman. She remained faithful to Qays in her heart. Years passed. Layla heard one of Majnun's verses sung at her own door by a passing minstrel. She sent for him. The minstrel did not know him. Layla sent her own poem back into the desert to find him. They never met again in this life. When Layla died, Majnun walked to her grave and lay down beside it and would not be moved. He died there. The desert wind, the storyteller says, still carries verses through the dunes that no one has written."},
    {**_make("Filipino Maria-Makiling forest-spirit tale", "Filipino-watercolor", "Maria-Makiling forest-spirit tale"),
     "user_goal": "Here's my story I want to process — Filipino-watercolor style: On the slopes of Mount Makiling there once lived a forest spirit named Maria. She tended the animals and the plants and watched over the village below. One day she fell in love with a young farmer who climbed her mountain to hunt. The farmer loved her too. They met by a small stream every evening. When his village was struck by famine, Maria filled the farmer's basket with ginger that turned to gold by the time he reached his home. The farmer's neighbors grew jealous. The Spaniards came and tried to take Maria for themselves. The farmer was killed. Maria grieved so deeply that she withdrew from her mountain forever. They say she still lives in the heart of the volcano, and that on certain misty mornings you can see her shape in the clouds at the summit, watching over the people who once knew her."},
    {**_make("Mexican La-Llorona ghost-tale", "Mexican-retablo", "La-Llorona ghost-tale"),
     "user_goal": "Here's my story I want to process — Mexican-retablo style: In a colonial town long ago there was a woman named María who fell in love with a wealthy stranger from Spain. He married her, and she bore him two sons. The years passed. He grew tired of her. He took up with a younger woman from the city. María, in despair and rage, took her two sons to the river and drowned them. When she understood what she had done, she walked into the river herself. They say her ghost still wanders the riverbanks at night, weeping and calling out for her children. The villagers warn their own children: if you hear a woman crying near the water, do not answer. The mothers tell the story not to frighten but to teach: that grief without forgiveness becomes hunger that walks the earth, and that the only thing that turns hunger back into a soul is the kindness of strangers."},
    {**_make("Mongolian Temüjin-childhood folktale", "Mongolian-folk-art", "young-Temüjin-on-the-steppe folktale"),
     "user_goal": "Here's my story I want to process — Mongolian-folk-art style: Long before he was Genghis Khan, the boy Temüjin lived with his mother and brothers on the cold steppe. His father had been killed by a rival tribe. His own clan had abandoned him and his family because he was a child and could not protect them. The winter that followed was the worst the steppe had seen in a generation. His mother fed him and his brothers on roots and rabbits. One brother stole food from another. Temüjin and the brothers killed him. When the mother heard, she did not weep, but she told Temüjin: a wolf does not eat its own pack. Temüjin remembered. When he became khan he gathered the abandoning clans and gave them a choice: join him or be put to the sword. Most joined. He led them across the world and they were never abandoned again. The mother, the storyteller says, lived to see all of it."},
    {**_make("Hawaiian Pele-and-Hi'iaka sister myth", "Polynesian-tapa-cloth", "Pele-and-Hi'iaka sister myth"),
     "user_goal": "Here's my story I want to process — Polynesian-tapa-cloth style: The volcano-goddess Pele had many sisters, but the youngest, Hi'iaka, was her favorite. One day Pele's spirit traveled to the island of Kauai and fell in love with a chief named Lohiau. She returned to her own body on the Big Island and asked Hi'iaka to fetch Lohiau and bring him to her. Hi'iaka set out across the islands. The journey took longer than either sister had expected. Hi'iaka faced demons, water-spirits, and the coldness of strange villages. She arrived at Lohiau's island to find him dead. She brought him back to life with chants and herbs. They traveled home together. Pele, jealous of how long the journey had taken, killed Hi'iaka's beloved friend Hopoe by burying her in lava. Hi'iaka, in grief, took Lohiau as her own. The sisters did not speak again for many years. The fire of Pele's mountain, the storyteller says, still has not cooled."},
    {**_make("Korean Tangun founding-myth", "Korean-minhwa", "Tangun-and-the-bear-woman founding-myth"),
     "user_goal": "Here's my story I want to process — Korean-minhwa style: In the time before there were kingdoms, the son of the sky-god Hwanin came down to the earth and stood on the peak of Mount Taebaek. He was Hwanung. A tiger and a bear came to him, both wishing to become human. Hwanung gave them twenty cloves of garlic and a bundle of mugwort and told them: stay in a cave for one hundred days and eat only this and avoid the sunlight. The tiger could not endure it and left after a few days. The bear endured the full hundred days. On the hundredth day she emerged as a woman. Hwanung married her. Their son was Tangun. Tangun founded the first Korean kingdom on Mount Taebaek and ruled for one thousand years. Then he became a mountain spirit. The Koreans say that every Korean is descended in spirit from the bear-woman, who endured what the tiger would not."},
    {**_make("Greek Daphne-and-Apollo myth", "Greek-vase-painting", "Daphne-and-Apollo myth"),
     "user_goal": "Here's my story I want to process — Greek-vase-painting style: Apollo, the golden god of the sun, had angered Eros, the small god of love. In revenge, Eros shot Apollo with a gold arrow that made him fall in love and shot the river-nymph Daphne with a lead arrow that made her unable to love. Apollo pursued Daphne through the forests of Thessaly. She ran. He was faster. She could feel his breath behind her. As he reached for her, she cried out to her father, the river-god, to save her. Her father heard. Bark grew over Daphne's skin. Her arms became branches. Her hair became leaves. By the time Apollo's hand closed, he held only the trunk of a young laurel tree. He wept. He wove a wreath of laurel and crowned himself with it, and from that day every poet and athlete the gods favored has worn a wreath of laurel. The tree, the storytellers say, still flinches in the warmth of the sun."},
    {**_make("Andean Pachamama tale", "Inca-textile", "Pachamama mother-earth tale"),
     "user_goal": "Here's my story I want to process — Inca-textile style: Pachamama is the mother-earth of the Andean people. She is older than the mountains. Her body is the soil and the rivers and the high pastures. Long ago, when the Inca emperor was building Machu Picchu, the workers grew weak from the thin air. They could not lift the stones. The emperor consulted with his priestess. The priestess walked alone to a high pasture, knelt on the earth, and asked Pachamama for help. Pachamama did not speak in words. She breathed warm air into the lungs of the workers. She softened the stones so that they could be carved. She filled the springs of Machu Picchu with water that did not freeze. The city was built. The emperor offered Pachamama a thousand gifts. She accepted only one — that every farmer in the empire, before he tilled his field each spring, would bow once and ask permission. The Andean farmers still bow, today."},
    {**_make("Yoruba Sango-thunder-god tale", "Yoruba-adire-cloth", "Sango-thunder-god tale"),
     "user_goal": "Here's my story I want to process — Yoruba-adire-cloth style: Long ago Sango was a king of the Yoruba people. He was a fierce king and a proud one. He could spit fire from his mouth. His own wives could not stand close to him without burning. One day Sango quarreled with his closest counselor and accidentally burned down his own palace, killing many of his own family. In grief and shame Sango walked into the forest alone and hanged himself from the iroko tree. But Sango did not die in the way other men die. He climbed up into the sky on a long iron chain. He became the orisha of thunder and lightning. When the storms come over Yoruba land, the elders say Sango is fighting the spirits of his old enemies in the clouds. The thunder is his anger. The rain that falls after is his sorrow. The lightning, they say, is the chain he climbed."},
    {**_make("Tibetan Milarepa transformation-tale", "Tibetan-thangka", "Milarepa transformation-tale"),
     "user_goal": "Here's my story I want to process — Tibetan-thangka style: Milarepa was born to a wealthy family in Tibet. When he was still a boy his father died and his uncles seized everything that should have come to him. His mother, in rage, sent the young Milarepa to study black magic. He learned it. He used a great spell to bring down the roof of his uncles' great hall during a wedding feast, killing thirty-five of his relatives. When his rage cooled, Milarepa was horrified by what he had done. He sought a teacher to undo the karma. He found Marpa, who was a hard master. Marpa made him build a tower with his own hands, then tear it down, then build it again, six times. Milarepa endured. After many years he reached enlightenment in a cave high in the mountains. He sang songs of the dharma to the people who came to find him. The songs are still sung in Tibet today."},
    {**_make("Maori Maui-fishhook myth", "Maori-whakairo-carving", "Maui-fishhook myth"),
     "user_goal": "Here's my story I want to process — Maori-whakairo-carving style: Maui was a young man who had been adopted by the gods of the sea. He was small and clever. His older brothers were tall and strong and did not respect him. One day he hid in their canoe so that he could come fishing with them. They went out far past the open sea. Maui revealed himself. The brothers were angry but could not turn back. Maui asked his brothers for a piece of bait. They refused. Maui struck his own nose, drew blood, and used it for bait. He cast his hook into the sea. Something enormous took the hook. Maui sang the song of strength his grandmother had taught him. The brothers helped him pull. What he pulled up was Te Ika-a-Māui, the Great Fish of Maui — the North Island of Aotearoa. The brothers, in their hunger, began to cut it before the proper rites were said. The mountains and valleys of the North Island are the marks of their cuts."},
    {**_make("Brazilian Saci-Pererê trickster tale", "Brazilian-cordel-illustration", "Saci-Pererê trickster tale"),
     "user_goal": "Here's my story I want to process — Brazilian-cordel-illustration style: Saci-Pererê is a small one-legged trickster spirit who appears in the back-country of Brazil. He wears a red cap and smokes a pipe. He moves through the world inside a small whirlwind. He braids the manes of horses into impossible knots and hides things and burns dinners. He cannot be beaten by force. The way to catch a Saci is to throw a sieve into his whirlwind, which traps him, and then take his red cap. Without his cap a Saci must grant any wish you ask of him to get it back. A young farmer once caught a Saci this way. He asked the Saci for a fortune. The Saci pointed to a place under a tree on the farmer's own land. The farmer dug. He found his own father's old saving-jars buried for a rainy day, full of coins. The Saci had not given him a fortune. He had reminded him of one. The farmer let the Saci go and never set the sieve again."},
    {**_make("Italian Pinocchio classic", "classic-storybook", "Pinocchio classic"),
     "user_goal": "Here's my story I want to process — classic-storybook style: An old woodcarver named Geppetto carved a puppet from a piece of magic pine. He named the puppet Pinocchio. The puppet came to life in his hands, but he was made only of wood, and his heart was made only of carving. Pinocchio ran away. He fell in with a wicked fox and a wicked cat. He lied. Every time he lied his nose grew. He visited a country where bad children are turned into donkeys. He was nearly turned into one himself. He swam through the body of a great whale to find Geppetto, who had gone to sea looking for him. They were saved. Pinocchio worked very hard, gave away his last coins to a kind family, and on the morning his goodness was complete, he woke up to find that he was a real boy. Geppetto wept. The wood that Pinocchio had been carved from sat on the windowsill, empty, all that was left of who he had been."},
    {**_make("Chinese Monkey-King origin tale", "Chinese-ink-wash", "Monkey-King-Sun-Wukong origin tale"),
     "user_goal": "Here's my story I want to process — Chinese-ink-wash style: On the Mountain of Flowers and Fruit there was a great stone that had been on the mountain since the beginning of the world. The stone, fed by sun and moon and rain for ages, finally cracked open and a stone monkey sprang out of it. The monkey was clever. He led the other monkeys of the mountain into a hidden cave behind a waterfall and was made their king. He grew bored with monkey life. He sailed across the seas and learned magic from a Daoist master, and the master taught him seventy-two transformations and how to ride the clouds. He became Sun Wukong, the Monkey King. He was prouder than any sky-god allowed. He stole the peaches of immortality from the heavenly orchard. He made war on the celestial army. The Buddha himself trapped him under a mountain to teach him patience. Five hundred years later, a young monk passing south to bring back the sutras unsealed the mountain. The Monkey King became his disciple and his protector."},
    {**_make("Russian Vasilisa-and-Baba-Yaga tale", "Bilibin-style", "Vasilisa-and-Baba-Yaga folktale"),
     "user_goal": "Here's my story I want to process — Bilibin-style: Vasilisa was a young Russian girl whose mother had died when she was small. Her stepmother was cruel. Her stepsisters were lazy. One winter night the fire in the cottage went out. The stepmother sent Vasilisa into the deep forest to ask Baba Yaga for fire. Vasilisa carried the small wooden doll her dead mother had given her. The doll guided her. Baba Yaga's hut stood on chicken legs in a clearing. Baba Yaga set Vasilisa to impossible tasks — to sort grain from poppy seed, to wash a hut full of laundry — and the doll did them in the night. Vasilisa endured Baba Yaga's questions without showing fear. Baba Yaga, displeased that Vasilisa had been blessed by her dead mother, gave her the fire she had come for and sent her home. The fire burned the cruel stepmother to ashes. Vasilisa was free. The doll, the storyteller says, still sits on the windowsill of every Russian house where a daughter remembers her mother."},
    {**_make("Hindu Hanuman-flying-mountain tale", "Pattachitra", "Hanuman-flying-mountain tale"),
     "user_goal": "Here's my story I want to process — Pattachitra style: When Lakshmana, the brother of Rama, fell in battle struck by a poisoned arrow, the only cure was a healing herb that grew on the slopes of a mountain in the high Himalayas. Hanuman, the loyal vanara warrior, leapt across half of India to find it. He reached the mountain by dawn. The herbs were many and they all looked alike. Hanuman did not know which one to pick. He could not tell. He knelt for one moment to think. Then he stood up, wrapped his arms around the entire mountain, lifted it into the sky, and flew with it back to the battlefield. The healers searched the mountain and found the herb. Lakshmana was saved. Hanuman returned the mountain to the Himalayas, exactly where he had taken it from, and bowed to the mountain in apology for moving it. The Himalayas, the storytellers say, still bear the imprint of Hanuman's hands on one of its peaks."},
    {**_make("Sami reindeer-yoik tale", "Sami-frame-drum-painting", "Sami reindeer-yoik tale"),
     "user_goal": "Here's my story I want to process — Sami-frame-drum-painting style: A young Sami herder named Sárá followed her father's reindeer across the tundra each year, from the lowland forests in the winter to the high mountains in the summer. There was one old reindeer, white-flanked, with one bent antler, that her father had said belonged to the mountain spirits. Sárá's father had refused to butcher it. When her father died, the new herd-master came and ordered the white-flanked reindeer killed. Sárá took her grandfather's frame drum and her own yoik-song and walked alone with the reindeer up onto the mountain. She did not return that night. The next morning the new herd-master searched. He found Sárá's frame drum at the foot of the highest cliff. He found Sárá at the top, sleeping safely, alive, and the white-flanked reindeer beside her. The new herd-master left the reindeer alone after that. Sárá's yoik became one of the songs that Sami children still learn from their grandmothers."},
    {**_make("Cambodian Reamker-Hanuman episode", "Khmer-bas-relief", "Reamker-Hanuman episode"),
     "user_goal": "Here's my story I want to process — Khmer-bas-relief style: In the Cambodian Reamker, the great epic version of the Indian Ramayana, Hanuman the white monkey crosses the southern sea to the kingdom of the demon-king Ravana. He goes to find the lost queen Sita. The sea is wider than any monkey can leap. Hanuman holds his breath and grows to the size of a mountain. He leaps. The clouds part around him. He lands on the island of the demon-king and walks unseen through the gardens until he finds Sita weeping under a tree. He shows her the ring of her husband Rama. She believes him. He sets her at peace. Then, before he leaves, he allows the demon-guards to capture him. He is brought before Ravana. They set his tail on fire as a punishment. With his burning tail, Hanuman leaps from rooftop to rooftop, setting Ravana's whole city ablaze. Then he returns across the sea to Rama with the news of Sita."},
    {**_make("Egyptian Bastet-and-the-mice tale", "Egyptian-papyrus", "Bastet-and-the-mice tale"),
     "user_goal": "Here's my story I want to process — Egyptian-papyrus style: When the cat-goddess Bastet was a young goddess, the mice of the Nile delta came to her in a delegation. They asked her, very politely, to convince her cats not to eat them. Bastet listened carefully. She told the mice that she could not ask her cats to give up their hunting, because hunting is what her cats were made for. But she would ask the mice to make her a single promise. The mice promised. The promise was: the mice would never steal from the offerings left at her temples. The mice agreed. The mice have kept the promise to this day. The cats have not stopped hunting. But every once in a while, the mice say, when one of them is caught, the cat will hesitate, just for a moment, remembering Bastet's bargain. The moment is enough for some mice to escape. The Egyptians say a mouse who escapes a cat has been blessed by Bastet."},
    {**_make("Inuit Raven-and-the-stolen-light myth", "Inuit-soapstone-carving", "Raven-and-the-stolen-light myth"),
     "user_goal": "Here's my story I want to process — Inuit-soapstone-carving style: Long ago the world was dark. The sun, the moon, and the stars were all hidden in three carved boxes in the lodge of a powerful chief who refused to share them. Raven, the trickster, decided to steal them. He turned himself into a hemlock needle and floated into the chief's daughter's drinking water. She drank him. He was reborn as her son. The chief loved his grandson, and could refuse him nothing. The grandson cried for the box that held the stars. The chief opened it. Raven, in the form of the boy, scattered the stars across the sky. He cried for the moon. The chief opened that box too. Raven hung the moon. He cried for the last box. The chief opened it. Raven became himself again, seized the sun in his beak, and flew up the smoke-hole of the lodge. His feathers, white before, were burned black. They are still black today."},
    {**_make("Welsh Branwen-daughter-of-Llŷr tale", "illuminated-manuscript", "Branwen-daughter-of-Llŷr tale"),
     "user_goal": "Here's my story I want to process — illuminated-manuscript style: Branwen, the daughter of Llŷr, was given in marriage to the king of Ireland to seal a peace between the two islands. She was kind and beautiful. The Irish, after a year, decided they had been insulted by the marriage. They banished Branwen to work as a kitchen-girl in her own husband's hall. She trained a starling. She wrote a letter. She tied it to the starling's leg. The starling flew across the Irish Sea to Wales. Her brother Bran the Blessed, a giant, waded across the sea after it. He crossed the sea on foot, and his army crossed in ships beside him. There was a great battle. Bran was killed. Branwen, in grief at the slaughter on both sides, died of a broken heart. She was buried in a quiet place beside the Alaw river. Her grave is still there. The Welsh, the storytellers say, do not start wars from kindness anymore."},
    {**_make("Persian Simurgh-and-the-young-prince tale", "Persian-miniature", "Simurgh-young-prince tale"),
     "user_goal": "Here's my story I want to process — Persian-miniature style: There was once a king of Persia whose son was born with white hair, like an old man. The king feared the omen and abandoned the boy in the mountains. The Simurgh, the great wise bird of the mountain Alborz, found the infant and raised him in her nest as her own. She fed him. She taught him the language of all things. Years passed. The boy became a young prince. The king of Persia, who had never recovered from his crime, dreamed of his son and went to find him. The Simurgh allowed it. She gave the prince three of her own feathers. She told him: when you have great need of me, burn one. The prince returned to Persia and ruled justly. He used the feathers only when he was older and his own son had been wounded in battle. The Simurgh came. She healed his son. She has watched the line of Persia from her mountain ever since."},
    {**_make("Mongolian Geser-saga episode", "Mongolian-folk-art", "Geser-saga horse-stealing episode"),
     "user_goal": "Here's my story I want to process — Mongolian-folk-art style: King Geser of Ling is the great epic hero of the Mongolian and Tibetan plateau. In one episode of his long saga, a demon-king from the north stole the prize horses of Geser's kingdom — a herd of one hundred mares with golden manes. Geser pursued the demon-king for nine days and nine nights across the steppe. On the tenth morning, Geser caught up. The demon-king refused to return the horses. Geser challenged him to a wrestling match for them. The demon-king was twice Geser's size. They wrestled for a day. They wrestled until both were bleeding. At the moment Geser's strength was failing, his guardian sky-spirit blew a small cool wind into his lungs. He found a second wind. He threw the demon-king into a deep pit and sealed it with a boulder. He led the hundred mares back to Ling. They are still, the storytellers say, the best horses on the steppe."},
    {**_make("Hawaiian Maui-slowing-sun myth", "Polynesian-tapa-cloth", "Maui-slowing-sun myth"),
     "user_goal": "Here's my story I want to process — Polynesian-tapa-cloth style: In the early days of the world, the sun raced across the sky so fast that the kapa cloth could not be dried before the sun set, the breadfruit could not be cooked, and the women could not finish their work. The trickster Maui decided to do something. He climbed Mount Haleakalā in the night with sixteen ropes braided from his sister's hair. He waited at the summit. As the sun rose, he caught its first ray with his rope. The sun struggled. Maui wrapped a rope around each of the sun's sixteen arms. The sun begged for its life. Maui agreed to let the sun go on one condition: that the sun would slow down for half of every year, so that the people of the islands could finish their work. The sun agreed. To this day, the storytellers say, summer is the season the sun keeps its promise. Winter is the season the sun is in a hurry."},
    {**_make("Korean Princess Pyeonggang-and-fool-Ondal tale", "Korean-minhwa", "Princess-Pyeonggang-and-fool-Ondal tale"),
     "user_goal": "Here's my story I want to process — Korean-minhwa style: Princess Pyeonggang of Goguryeo was a small girl who cried often, and her father the king teased her: keep crying and I'll marry you to fool Ondal, the village idiot. He repeated the joke for years. When the princess was old enough to be married, the king arranged a noble match. The princess refused. She had thought about her father's joke. She had decided it was a promise. She walked out of the palace alone and went to find Ondal. She found him. He was a poor woodcutter caring for his blind mother. The princess gave him her royal jewelry. She taught him to read. She taught him archery and horsemanship. Ondal grew into a great general. He led the Goguryeo armies in many victories. The king accepted him. When Ondal died in battle, his coffin would not move from the spot until the princess came and spoke to it. She spoke. The coffin lifted. The princess buried him. She was a great commander herself for the rest of her life."},
    {**_make("Greek Persephone-underworld myth", "Greek-vase-painting", "Persephone-underworld myth"),
     "user_goal": "Here's my story I want to process — Greek-vase-painting style: Persephone was the daughter of Demeter, the goddess of the harvest. She was gathering flowers in a meadow when the earth opened beneath her and Hades, the king of the underworld, took her down to be his queen. Demeter searched for her for many days and would not let the harvest grow until her daughter was returned. The world was about to starve. Zeus ordered Hades to release Persephone. Hades obeyed, but he gave Persephone six pomegranate seeds before she left. She ate them. The seeds bound her to the underworld for six months of every year. Now, every spring, when Persephone returns to her mother, the harvest grows again. Every winter, when she descends to her husband, the earth sleeps. The Greeks say there is no greater grief than a mother whose daughter has been taken, and no greater joy than her daughter's return — and that this is the rhythm by which all the seasons of the world are measured."},
    {**_make("Andean Inkarrí return-prophecy", "Inca-textile", "Inkarrí return-prophecy tale"),
     "user_goal": "Here's my story I want to process — Inca-textile style: When the Spaniards killed the last Inca emperor, his name was Atahualpa. The conquistadors decapitated him and his body was buried in one place and his head was buried far away. The Andean people say his body and his head are slowly growing back together under the earth. They are still growing. When his body is whole again, he will rise from the earth. He will walk through the high passes. The condors of the Andes will follow him. The mountains will speak to him. He will reclaim what was taken from his people. The Andean storytellers say no one knows when. They have been waiting for five hundred years. They keep planting their potatoes. They keep singing the songs in their old language. They say: a body grows slowly under the earth, but a body grows. The day will come. We are patient. We were always patient. Patience is what mountains are made of."},
    {**_make("Yoruba Oshun-river-goddess tale", "Yoruba-adire-cloth", "Oshun-and-the-drying-river tale"),
     "user_goal": "Here's my story I want to process — Yoruba-adire-cloth style: Oshun is the river-goddess of the Yoruba. She is the goddess of fresh water, of love, of laughter. Once long ago the river of Oshun began to dry up. The villagers along its banks did not know why. They asked the elders. The elders said: it is because no one has danced for Oshun in many years. The young women of the village put on yellow cloth and went to the river. They danced. They sang. They poured honey into the water. They left small mirrors on the rocks for Oshun to look in. By morning the river was full again. Oshun, the elders say, never stops loving the people. The people just sometimes forget to love her back. The women of that village still go to the river every year in yellow cloth and dance for her, and the river has never dried again."},
    {**_make("Tibetan Mani-stone tale", "Tibetan-thangka", "Mani-stone-of-the-shepherd tale"),
     "user_goal": "Here's my story I want to process — Tibetan-thangka style: A poor shepherd in the high mountains of Tibet wanted to build a pile of mani stones — stones with the mantra carved into them — at the pass where the wind was always strong. He had no skill in carving. He could not write. He could only carve the same line over and over: a single shaky letter. He carved it on every stone he found. The pile grew slowly. He died one winter at the pass. A great lama passed that way the following spring. He saw the pile. He read the stones. He wept. He told the shepherd's village: this man, who could write only one letter, has earned more merit than I have in all my years of study. He carved with his whole heart. The village built a small shrine at the pass over the shepherd's pile. The lama walked back to his monastery and said nothing for seven days. Then he asked his students to carve only what they meant."},
    {**_make("Maori Hine-nui-te-pō-and-Maui myth", "Maori-whakairo-carving", "Hine-nui-te-pō-and-Maui myth"),
     "user_goal": "Here's my story I want to process — Maori-whakairo-carving style: Maui, the trickster, had stolen fire and slowed the sun and pulled the islands from the sea. He decided he could also defeat death. Death was Hine-nui-te-pō, the great goddess of the night. She slept far in the west. Maui crept up to her with his bird companions and told them: do not laugh. He turned himself small as a worm. He began to crawl into her body. If he could pass through her and out her mouth, he could undo death. The bird companions held their breath. But the small fantail, near the end, could not help itself. It laughed. Hine-nui-te-pō woke. She closed her body around Maui and crushed him. So death entered the world to stay. The Maori say: it is the fault of the fantail that we die. They also say: it is also the fault of all of us who could not, in some moment, hold a laugh in."},
    {**_make("Brazilian Iara-river-mermaid tale", "Brazilian-cordel-illustration", "Iara-river-mermaid tale"),
     "user_goal": "Here's my story I want to process — Brazilian-cordel-illustration style: Iara is a freshwater mermaid of the Amazon. She has long green hair, dark eyes, and a voice that draws fishermen into the river to drown. A young hunter named João once heard her song from his canoe at dusk. He covered his ears with wax and rowed back to shore. The next night he heard her again. He did not row away this time. He listened. He pulled his canoe to her rock. He spoke to her. He did not look at her face. He told her she was beautiful and that he was afraid. Iara was so surprised by his honesty that she did not pull him under. She talked with him until dawn. She spared him. Every season after that, João brought her a small offering — a flower, a feather, a stone — and never looked at her face. He lived to be an old man. The river never took him. They say if you speak honestly to Iara, she may, sometimes, let you go."},
    {**_make("Italian Befana-wandering-woman tale", "classic-storybook", "Befana-wandering-woman tale"),
     "user_goal": "Here's my story I want to process — classic-storybook style: La Befana was an old woman of Italy who, on a winter evening long ago, was sweeping her cottage when three travelers stopped at her door asking for directions. They were following a star, they said, to bring gifts to a newborn king. They invited her to come with them. La Befana said no, she was too busy with her sweeping. They went on without her. By morning, La Befana had changed her mind. She gathered some small gifts and a broom and ran out to find the travelers. She could not find them. She has been searching ever since. Every year on the eve of Epiphany she flies on her broom across the rooftops of Italy, looking into the windows of every house, leaving small gifts for the children in case any of them should turn out to be the king she missed. She never gives up. She never finds him. But the children of Italy still hang their stockings for La Befana every year."},
    {**_make("Chinese Mid-Autumn Chang'e-moon tale", "Chinese-ink-wash", "Chang'e-moon-goddess tale"),
     "user_goal": "Here's my story I want to process — Chinese-ink-wash style: Long ago there were ten suns in the sky. Hou Yi, the great archer, shot down nine of them with his bow. The remaining sun thanked him. The Queen Mother of the West gave Hou Yi an elixir of immortality as a reward, but only enough for one person. Hou Yi did not want to live forever without his wife Chang'e. He hid the elixir. One of his apprentices, a wicked man, came to steal it while Hou Yi was away. Chang'e knew the apprentice would take it and rule the world badly. She drank the elixir herself. She rose into the sky and was carried to the moon, where she lives to this day with a single jade rabbit. Hou Yi, when he returned, looked up at the moon and could see her. Every year on the night of the full moon in autumn, the people of China leave moon cakes on their windowsills so that Chang'e knows she is not forgotten."},
    {**_make("Russian Snegurochka snow-maiden tale", "Bilibin-style", "Snegurochka snow-maiden tale"),
     "user_goal": "Here's my story I want to process — Bilibin-style: An old man and an old woman in a village in Russia had no children, and one winter, in their loneliness, they built a child out of snow. They gave her sticks for arms and dark stones for eyes. To their amazement, the snow-girl came alive. They named her Snegurochka. She grew as the winter wore on. She helped her parents in the cottage. She danced with the village children when they came in from the cold. She was happy. When the spring came and the snow began to melt, Snegurochka grew thinner. The other children invited her to leap a fire on the longest day of summer for good luck. She did not want to disappoint them. She leapt the fire. She melted in the heat. She rose up as a small white cloud and was lost in the blue sky. The old couple wept. They did not build another snow-girl. They had loved her too much to make a copy of her."},
    {**_make("Hindu Savitri-and-Yama tale", "Pattachitra", "Savitri-and-Yama tale"),
     "user_goal": "Here's my story I want to process — Pattachitra style: Princess Savitri loved Satyavan, who was destined to die one year after their marriage. Savitri married him anyway. On the day Yama, the god of death, came to take Satyavan's spirit, Savitri followed him. Yama walked through the forest. Savitri walked behind him. Yama, surprised, told her to go home. She refused. Yama, impressed by her devotion, offered her any boon she wished — except the life of her husband. Savitri asked for sons. Yama granted it. She kept walking behind him. Yama, even more impressed, offered another boon. Savitri asked for the kingdom of her dead father-in-law to be restored. Yama granted it. She kept walking. Yama said: I cannot give you the life of your husband. Savitri said: but you have just promised me sons, and how shall I have sons without a husband? Yama looked at her. He bowed. He gave Satyavan back. Savitri, the storytellers say, was the most patient woman who ever loved a man."},
    {**_make("Sami sieidi-stone-spirit tale", "Sami-frame-drum-painting", "sieidi-stone-spirit tale"),
     "user_goal": "Here's my story I want to process — Sami-frame-drum-painting style: A young Sami fisherman was crossing a high lake to reach a stand of sieidi stones — stones the old people said held the spirits of the lake. The lake was rough. His boat began to take water. He spoke to the sieidi stones across the lake and promised them his best fish if they would let him reach the shore. The wind died. The lake calmed. He reached the stones. He left his best fish on the largest stone, as he had promised. He went home. The next day his father asked him: where did you fish? He told the truth. His father grew angry — they did not have enough food to leave fish for stones. The son returned to the lake the next morning to retrieve the fish. The fish was gone. In its place was a small bag woven of reeds. The bag held one whole salmon, far larger than any he had caught. The sieidi stones, the old people said, never refuse a true gift."},
    {**_make("Cambodian Thmenh-Chey trickster tale", "Khmer-bas-relief", "Thmenh-Chey trickster tale"),
     "user_goal": "Here's my story I want to process — Khmer-bas-relief style: Thmenh Chey was a Cambodian peasant boy whose cleverness was greater than any king's. From the time he was small, he tricked the abbot of his village monastery, the local merchants, and finally the king himself. The king tried to outwit him. The king failed every time. The king sent him to a foreign land in the hope that the foreign king would have him killed. The foreign king demanded Thmenh Chey pour a sea into a vase. Thmenh Chey replied: certainly, sire — bring me one bowl of the sea, and I will pour it into the vase. The foreign king laughed and welcomed him as a guest. He returned to Cambodia richer than before. The Cambodian king tried one last test. He told Thmenh Chey to bring him the moon. Thmenh Chey said: certainly, sire — bring me the longest ladder ever made. The king laughed too and gave up. Thmenh Chey, the storytellers say, was the only commoner the kings of Cambodia ever loved more than they feared."},
    {**_make("Filipino Bernardo-Carpio sleeping-hero myth", "Filipino-watercolor", "Bernardo-Carpio sleeping-hero myth"),
     "user_goal": "Here's my story I want to process — Filipino-watercolor style: Bernardo Carpio was a giant born to a Filipino noblewoman and a Spanish nobleman in the time of the Spanish colony. His strength was greater than any man's. He could wrestle ten carabao at once. He grew angry at the Spaniards' treatment of his mother's people. He fought them. He fought them so well that the colonial governor sought a way to defeat him by trickery. The governor's sorcerer trapped Bernardo Carpio in a cleft between two great mountains in the Sierra Madre. The mountains pressed against him from both sides. Bernardo Carpio is still there. The Filipino people say: when Bernardo Carpio shifts his shoulders, the earth shakes — that is the source of every earthquake in the islands. They also say: one day Bernardo Carpio will break free from the mountains, and on that day the islands will know who they were always meant to be. The mountains have not yet released him. The earthquakes still come."},
    {**_make("Egyptian Ma'at-and-the-feather tale", "Egyptian-papyrus", "Ma'at-and-the-feather-of-truth tale"),
     "user_goal": "Here's my story I want to process — Egyptian-papyrus style: When an Egyptian died, the soul was led by jackal-headed Anubis to the great hall of judgment. There the heart of the dead was placed on one side of a great scale. On the other side was the feather of Ma'at, the goddess of truth. If the heart was lighter than the feather, the soul could pass into the field of reeds and live forever. If the heart was heavier than the feather, the soul was eaten by the demon Ammit, who waited under the scale. There was a fisherman named Senedjem who lived a quiet life and did not think he had done anything special. He died and stood before the scale. His heart was lighter than the feather. He had been kind to his wife. He had been honest with the tax-collector. He had given alms when he could. The Egyptian priests said: it is the smallest things that make a heart light. Senedjem went to the field of reeds and was happy."},
    {**_make("Welsh Lludd-and-Llefelys tale", "illuminated-manuscript", "Lludd-and-Llefelys tale"),
     "user_goal": "Here's my story I want to process — illuminated-manuscript style: King Lludd of Britain had three plagues that troubled his kingdom. First, an invading people called the Coraniaid heard every word spoken on the wind. Second, every May Eve a terrible scream rose up that withered the crops. Third, all the food in the king's storehouses disappeared each night. Lludd consulted his wise brother Llefelys, the king of France. Llefelys told him, through a brass tube to defeat the wind-listening, the secrets to defeat each plague. Lludd brewed insects in water and threw the water on the Coraniaid; they perished. He buried two fighting dragons in a great vat of mead at the center of the island; they slept and the scream ceased. He stayed awake himself and caught the giant who had been stealing the food; he wrestled the giant and bound him to serve the kingdom. Britain prospered. Lludd, the storytellers say, ruled in peace until he died of nothing but old age."},
    {**_make("Hawaiian Lonely-fisherman-and-shark-god tale", "Polynesian-tapa-cloth", "lonely-fisherman-and-shark-god tale"),
     "user_goal": "Here's my story I want to process — Polynesian-tapa-cloth style: A young fisherman in the Big Island had no family and no friends. He lived alone in a hut by the shore. Every morning he went out in his small canoe and fished. One day a shark followed his canoe. The fisherman did not throw a spear. He threw the smallest of his fish to the shark. The shark ate it. The fisherman did this every day. The shark grew to know him. After many years the fisherman became old and ill. He could no longer fish. The shark came to his door — for the shark was a kupua, a shape-shifter, and he had taken the form of a man as well as a shark. The shark-man brought the fisherman fish every day until the fisherman died peacefully in his hut. The shark-man buried him beside the shore. The Hawaiians say: every time you give a fish to a stranger, you are making a friend who may become your kupua when you most need one."},
    {**_make("Chinese Niulang-and-Zhinü star-crossed tale", "Chinese-ink-wash", "Niulang-and-Zhinü star-crossed tale"),
     "user_goal": "Here's my story I want to process — Chinese-ink-wash style: Niulang was a poor cowherd. Zhinü was a weaver-girl who was also the seventh daughter of the celestial emperor. She came down from heaven one day with her sisters to bathe in a lake. Niulang stole her fairy robe so that she could not return. They married. They had two children. They were happy. Years later her mother, the celestial empress, found out. She was furious. She came down and dragged Zhinü back to heaven. Niulang followed with the children. The empress drew her hairpin across the sky and made a great river — the Milky Way — to keep them apart forever. The two were inconsolable. The magpies of the world saw their grief. Each year on the seventh day of the seventh lunar month, all the magpies of the world fly up and form a bridge across the Milky Way. Niulang and Zhinü are allowed to cross and meet for one night. The Chinese still celebrate that night every year."},
    {**_make("Russian Firebird-and-Ivan Tsarevich tale", "Bilibin-style", "Firebird-and-Ivan-Tsarevich tale"),
     "user_goal": "Here's my story I want to process — Bilibin-style: The tsar's apple-tree of golden apples had been raided every night by a thief. The youngest of the tsar's three sons, Ivan, hid in the orchard at midnight. The thief was a great firebird with feathers of red gold. Ivan caught one of her tail-feathers as she flew. The tsar wished to have the firebird itself. He sent his three sons after her. Ivan rode his small grey wolf, and the wolf was wiser than any horse. The wolf told Ivan: do not take the firebird's gold cage. Take only the bird. Ivan took the cage anyway. He was caught. The firebird's owner — a tsar of another land — agreed to spare him in exchange for the horse with the gold mane from yet another land. Ivan rode on. He took the horse. He took its gold halter against the wolf's warning. He was caught again. Many trials passed before Ivan finally returned home with the firebird, the horse, and a princess he had not expected to love. The wolf, the storytellers say, never said I told you so."},
    {**_make("Korean Tale-of-Chunhyang-and-Yi-Mongryong", "Korean-minhwa", "Chunhyang-and-Yi-Mongryong tale"),
     "user_goal": "Here's my story I want to process — Korean-minhwa style: Chunhyang was the daughter of a Joseon-era courtesan. Yi Mongryong was the son of the local governor. They met under a great willow tree on the night of the Dano festival and fell in love. They married in secret. Yi Mongryong had to leave to study in the capital. He promised to return. Years passed. A new governor came to the village — a cruel man — and demanded Chunhyang serve him as concubine. She refused. He had her tortured. She refused again. The villagers wept for her. Word reached Yi Mongryong, now a royal inspector traveling in disguise. He returned to the village dressed as a beggar. The new governor was hosting a feast. The disguised Yi Mongryong burst in, revealed his royal seal, and arrested the governor on the spot for cruelty and corruption. He freed Chunhyang. They returned to the capital together. The Koreans say: a promise made under a willow tree is the strongest promise of all."},
]
